insert into entry_translations (id, entry_id, lang, kind, body, source_name) values ('a6379061-d9ff-54a7-a6f0-48d22074b621', '47007cfd-7c91-5a59-ac1c-be5e2517de0f', 'de', 'translation', 'gewiß, mit der Erschwernis ist Erleichterung.', 'Frank Bubenheim and Nadeem (Quran.com)') on conflict (id) do nothing;
