insert into religious_entries (id, type, arabic_text, surah_number, surah_name_ar, surah_name_en, ayah_number, source_id, source_reference, source_url, audio_url, audio_source, status, source_verified, verified_at) values ('e4182ec8-3bd5-5b03-a26d-82260deed336', 'quran', 'ٱلَّذِينَ ءَامَنُوا۟ وَتَطْمَئِنُّ قُلُوبُهُم بِذِكْرِ ٱللَّهِ ۗ أَلَا بِذِكْرِ ٱللَّهِ تَطْمَئِنُّ ٱلْقُلُوبُ', 13, 'الرعد', 'Ar-Ra''d', 28, 'f88c713d-6666-5de8-ac4d-65e5f14fe111', '13:28', 'https://quran.com/13/28', 'https://verses.quran.com/Alafasy/mp3/013028.mp3', 'Quran.com (Mishari al-Afasy)', 'published', true, now()) on conflict (id) do nothing;
insert into entry_translations (id, entry_id, lang, kind, body, source_name) values ('e13c116a-9c1d-5411-aa25-b626813f46ed', 'e4182ec8-3bd5-5b03-a26d-82260deed336', 'de', 'translation', '(Es sind) diejenigen, die glauben und deren Herzen im Gedenken Allahs Ruhe finden. Sicherlich, im Gedenken Allahs finden die Herzen Ruhe!', 'Frank Bubenheim and Nadeem (Quran.com)') on conflict (id) do nothing;
insert into entry_translations (id, entry_id, lang, kind, body, source_name) values ('c09f26a0-8465-5f75-ab7f-6bd53a0e15a8', 'e4182ec8-3bd5-5b03-a26d-82260deed336', 'en', 'translation', 'Those who have believed and whose hearts are assured by the remembrance of Allāh. Unquestionably, by the remembrance of Allāh hearts are assured."', 'Saheeh International (Quran.com)') on conflict (id) do nothing;
insert into entry_translations (id, entry_id, lang, kind, body, source_name) values ('ed3c439f-8905-5eb3-a3ea-ffd9397e85e9', 'e4182ec8-3bd5-5b03-a26d-82260deed336', 'ar', 'explanation', 'ذكر الله كيعطي للقلب السكينة والطمأنينة.', null) on conflict (id) do nothing;
