insert into entry_emotions (entry_id, emotion_id) values ('e4182ec8-3bd5-5b03-a26d-82260deed336', '803c63e3-df9a-5be1-a805-2b338c000ffb') on conflict do nothing;
insert into religious_entries (id, type, arabic_text, surah_number, surah_name_ar, surah_name_en, ayah_number, source_id, source_reference, source_url, audio_url, audio_source, status, source_verified, verified_at) values ('9d71dd80-0c3a-5af4-af82-94c21b0fcdd1', 'quran', 'لَا يُكَلِّفُ ٱللَّهُ نَفْسًا إِلَّا وُسْعَهَا ۚ لَهَا مَا كَسَبَتْ وَعَلَيْهَا مَا ٱكْتَسَبَتْ ۗ رَبَّنَا لَا تُؤَاخِذْنَآ إِن نَّسِينَآ أَوْ أَخْطَأْنَا ۚ رَبَّنَا وَلَا تَحْمِلْ عَلَيْنَآ إِصْرًا كَمَا حَمَلْتَهُۥ عَلَى ٱلَّذِينَ مِن قَبْلِنَا ۚ رَبَّنَا وَلَا تُحَمِّلْنَا مَا لَا طَاقَةَ لَنَا بِهِۦ ۖ وَٱعْفُ عَنَّا وَٱغْفِرْ لَنَا وَٱرْحَمْنَآ ۚ أَنتَ مَوْلَىٰنَا فَٱنصُرْنَا عَلَى ٱلْقَوْمِ ٱلْكَـٰفِرِينَ', 2, 'البقرة', 'Al-Baqarah', 286, 'f88c713d-6666-5de8-ac4d-65e5f14fe111', '2:286', 'https://quran.com/2/286', 'https://verses.quran.com/Alafasy/mp3/002286.mp3', 'Quran.com (Mishari al-Afasy)', 'published', true, now()) on conflict (id) do nothing;
insert into entry_translations (id, entry_id, lang, kind, body, source_name) values ('b7acadf5-c620-5ef5-aad3-125968c80ee8', '9d71dd80-0c3a-5af4-af82-94c21b0fcdd1', 'de', 'translation', 'Allah erlegt keiner Seele mehr auf, als sie zu leisten vermag. Ihr kommt (nur) zu, was sie verdient hat, und angelastet wird ihr (nur), was sie verdient hat. „Unser Herr, belange uns nicht, wenn wir (etwas) vergessen oder einen Fehler begehen. Unser Herr, lege uns keine Bürde auf, wie Du sie denjenigen vor uns auferlegt hast. Unser Herr, bürde uns nichts auf, wozu wir keine Kraft haben. Verzeihe uns, vergib uns und erbarme Dich unser! Du bist unser Schutzherr. So verhilf uns zum Sieg über das ungläubige Volk!', 'Frank Bubenheim and Nadeem (Quran.com)') on conflict (id) do nothing;
insert into entry_translations (id, entry_id, lang, kind, body, source_name) values ('75abafed-7536-5add-a6cf-f9c84651f1dc', '9d71dd80-0c3a-5af4-af82-94c21b0fcdd1', 'en', 'translation', 'Allāh does not charge a soul except [with that within] its capacity. It will have [the consequence of] what [good] it has gained, and it will bear [the consequence of] what [evil] it has earned. "Our Lord, do not impose blame upon us if we have forgotten or erred. Our Lord, and lay not upon us a burden like that which You laid upon those before us. Our Lord, and burden us not with that which we have no ability to bear. And pardon us; and forgive us; and have mercy upon us. You are our protector, so give us victory over the disbelieving people."', 'Saheeh International (Quran.com)') on conflict (id) do nothing;
insert into entry_translations (id, entry_id, lang, kind, body, source_name) values ('b372837b-4501-545a-a37c-b3631ad75f5a', '9d71dd80-0c3a-5af4-af82-94c21b0fcdd1', 'ar', 'explanation', 'الله ما كيكلف حتى واحد بأكثر من طاقتو.', null) on conflict (id) do nothing;
insert into entry_emotions (entry_id, emotion_id) values ('9d71dd80-0c3a-5af4-af82-94c21b0fcdd1', 'd7c0cea5-0d24-5079-a891-0600fda15645') on conflict do nothing;
insert into entry_emotions (entry_id, emotion_id) values ('9d71dd80-0c3a-5af4-af82-94c21b0fcdd1', '53cf081d-6a36-5e2d-a534-6f958407bd76') on conflict do nothing;
insert into entry_emotions (entry_id, emotion_id) values ('9d71dd80-0c3a-5af4-af82-94c21b0fcdd1', '8dde18d5-b9b7-5e14-a037-21ab395074c1') on conflict do nothing;
insert into religious_entries (id, type, arabic_text, surah_number, surah_name_ar, surah_name_en, ayah_number, source_id, source_reference, source_url, audio_url, audio_source, status, source_verified, verified_at) values ('3b3169ab-30be-58d4-a1e7-7b0709fd2caf', 'quran', 'وَلَا تَهِنُوا۟ وَلَا تَحْزَنُوا۟ وَأَنتُمُ ٱلْأَعْلَوْنَ إِن كُنتُم مُّؤْمِنِينَ', 3, 'آل عمران', 'Ali ''Imran', 139, 'f88c713d-6666-5de8-ac4d-65e5f14fe111', '3:139', 'https://quran.com/3/139', 'https://verses.quran.com/Alafasy/mp3/003139.mp3', 'Quran.com (Mishari al-Afasy)', 'published', true, now()) on conflict (id) do nothing;
insert into entry_translations (id, entry_id, lang, kind, body, source_name) values ('b3492cb6-0ec8-5235-a0ed-c6546acf951e', '3b3169ab-30be-58d4-a1e7-7b0709fd2caf', 'de', 'translation', 'Und werdet nicht schwach noch seid traurig, wo ihr doch die Oberhand haben werdet, wenn ihr gläubig seid.', 'Frank Bubenheim and Nadeem (Quran.com)') on conflict (id) do nothing;
insert into entry_translations (id, entry_id, lang, kind, body, source_name) values ('91559fc8-682a-511e-a895-bffe089b6e90', '3b3169ab-30be-58d4-a1e7-7b0709fd2caf', 'en', 'translation', 'So do not weaken and do not grieve, and you will be superior if you are [true] believers.', 'Saheeh International (Quran.com)') on conflict (id) do nothing;
insert into entry_translations (id, entry_id, lang, kind, body, source_name) values ('0b022a29-2123-5547-a2ac-54df2659c581', '3b3169ab-30be-58d4-a1e7-7b0709fd2caf', 'ar', 'explanation', 'ما تضعفوش وما تحزنوش، والله كيرفع المؤمنين.', null) on conflict (id) do nothing;
insert into entry_emotions (entry_id, emotion_id) values ('3b3169ab-30be-58d4-a1e7-7b0709fd2caf', '1de43123-dc44-5aea-ab96-c4a0dcff720d') on conflict do nothing;
insert into entry_emotions (entry_id, emotion_id) values ('3b3169ab-30be-58d4-a1e7-7b0709fd2caf', 'a745ea41-d3a7-5bc3-a25d-4524534d474e') on conflict do nothing;
insert into religious_entries (id, type, arabic_text, surah_number, surah_name_ar, surah_name_en, ayah_number, source_id, source_reference, source_url, audio_url, audio_source, status, source_verified, verified_at) values ('3b5e329c-7e77-515e-a900-580129562883', 'quran', 'إِلَّا تَنصُرُوهُ فَقَدْ نَصَرَهُ ٱللَّهُ إِذْ أَخْرَجَهُ ٱلَّذِينَ كَفَرُوا۟ ثَانِىَ ٱثْنَيْنِ إِذْ هُمَا فِى ٱلْغَارِ إِذْ يَقُولُ لِصَـٰحِبِهِۦ لَا تَحْزَنْ إِنَّ ٱللَّهَ مَعَنَا ۖ فَأَنزَلَ ٱللَّهُ سَكِينَتَهُۥ عَلَيْهِ وَأَيَّدَهُۥ بِجُنُودٍ لَّمْ تَرَوْهَا وَجَعَلَ كَلِمَةَ ٱلَّذِينَ كَفَرُوا۟ ٱلسُّفْلَىٰ ۗ وَكَلِمَةُ ٱللَّهِ هِىَ ٱلْعُلْيَا ۗ وَٱللَّهُ عَزِيزٌ حَكِيمٌ', 9, 'التوبة', 'At-Tawbah', 40, 'f88c713d-6666-5de8-ac4d-65e5f14fe111', '9:40', 'https://quran.com/9/40', 'https://verses.quran.com/Alafasy/mp3/009040.mp3', 'Quran.com (Mishari al-Afasy)', 'published', true, now()) on conflict (id) do nothing;
insert into entry_translations (id, entry_id, lang, kind, body, source_name) values ('344e6a50-ea18-58a4-a40e-ab4829c3ee4f', '3b5e329c-7e77-515e-a900-580129562883', 'de', 'translation', 'Wenn ihr ihm nicht helft, so hat Allah ihm (schon damals) geholfen, als diejenigen, die ungläubig waren, ihn als einen von Zweien vertrieben; als sie beide in der Höhle waren und als er zu seinem Gefährten sagte: Sei nicht traurig! Gewiß, Allah ist mit uns! Da sandte Allah Seine innere Ruhe auf ihn herab und stärkte ihn mit Heerscharen, die ihr nicht saht, und erniedrigte das Wort derjenigen, die ungläubig waren, während Allahs Wort (doch) das hohe ist. Allah ist Allmächtig und Allweise.', 'Frank Bubenheim and Nadeem (Quran.com)') on conflict (id) do nothing;
insert into entry_translations (id, entry_id, lang, kind, body, source_name) values ('0e41a5b9-4245-55a1-a509-cfced53e91ba', '3b5e329c-7e77-515e-a900-580129562883', 'en', 'translation', 'If you do not aid him [i.e., the Prophet (ﷺ)] - Allāh has already aided him when those who disbelieved had driven him out [of Makkah] as one of two, when they were in the cave and he [i.e., Muḥammad (ﷺ)] said to his companion, "Do not grieve; indeed Allāh is with us." And Allāh sent down His tranquility upon him and supported him with soldiers [i.e., angels] you did not see and made the word of those who disbelieved the lowest, while the word of Allāh - that is the highest. And Allāh is Exalted in Might and Wise.', 'Saheeh International (Quran.com)') on conflict (id) do nothing;
insert into entry_translations (id, entry_id, lang, kind, body, source_name) values ('59d46bf4-5aed-5d20-abbe-c2db04faf408', '3b5e329c-7e77-515e-a900-580129562883', 'ar', 'explanation', 'ما تحزنش، الله معانا. هادي كلمة طمأنينة وقت الشدة.', null) on conflict (id) do nothing;
insert into entry_emotions (entry_id, emotion_id) values ('3b5e329c-7e77-515e-a900-580129562883', '803c63e3-df9a-5be1-a805-2b338c000ffb') on conflict do nothing;
insert into entry_emotions (entry_id, emotion_id) values ('3b5e329c-7e77-515e-a900-580129562883', '2328342b-26af-598e-afd4-ad07b2bf2997') on conflict do nothing;
insert into religious_entries (id, type, arabic_text, surah_number, surah_name_ar, surah_name_en, ayah_number, source_id, source_reference, source_url, audio_url, audio_source, status, source_verified, verified_at) values ('299d2e77-a10b-5039-a374-ffe64b88f5b6', 'quran', 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱسْتَعِينُوا۟ بِٱلصَّبْرِ وَٱلصَّلَوٰةِ ۚ إِنَّ ٱللَّهَ مَعَ ٱلصَّـٰبِرِينَ', 2, 'البقرة', 'Al-Baqarah', 153, 'f88c713d-6666-5de8-ac4d-65e5f14fe111', '2:153', 'https://quran.com/2/153', 'https://verses.quran.com/Alafasy/mp3/002153.mp3', 'Quran.com (Mishari al-Afasy)', 'published', true, now()) on conflict (id) do nothing;
insert into entry_translations (id, entry_id, lang, kind, body, source_name) values ('410fae85-8aa1-5506-a9ab-097aa0e5ed14', '299d2e77-a10b-5039-a374-ffe64b88f5b6', 'de', 'translation', 'O die ihr glaubt, sucht Hilfe in der Standhaftigkeit und im Gebet! Allah ist mit den Standhaften.', 'Frank Bubenheim and Nadeem (Quran.com)') on conflict (id) do nothing;
insert into entry_translations (id, entry_id, lang, kind, body, source_name) values ('cf55b791-ba03-5c38-ab25-1e6193f3b986', '299d2e77-a10b-5039-a374-ffe64b88f5b6', 'en', 'translation', 'O you who have believed, seek help through patience and prayer. Indeed, Allāh is with the patient.', 'Saheeh International (Quran.com)') on conflict (id) do nothing;
insert into entry_translations (id, entry_id, lang, kind, body, source_name) values ('dee96b28-0459-5813-ac99-bc56b18e38b1', '299d2e77-a10b-5039-a374-ffe64b88f5b6', 'ar', 'explanation', 'الصبر والصلاة كيعاونو الإنسان، والله مع الصابرين.', null) on conflict (id) do nothing;
insert into entry_emotions (entry_id, emotion_id) values ('299d2e77-a10b-5039-a374-ffe64b88f5b6', '53cf081d-6a36-5e2d-a534-6f958407bd76') on conflict do nothing;
insert into religious_entries (id, type, arabic_text, surah_number, surah_name_ar, surah_name_en, ayah_number, source_id, source_reference, source_url, audio_url, audio_source, status, source_verified, verified_at) values ('0e475f9e-f9ab-5984-a4b7-711662f999f1', 'quran', 'مَا وَدَّعَكَ رَبُّكَ وَمَا قَلَىٰ', 93, 'الضحى', 'Ad-Duhaa', 3, 'f88c713d-6666-5de8-ac4d-65e5f14fe111', '93:3', 'https://quran.com/93/3', 'https://verses.quran.com/Alafasy/mp3/093003.mp3', 'Quran.com (Mishari al-Afasy)', 'published', true, now()) on conflict (id) do nothing;
insert into entry_translations (id, entry_id, lang, kind, body, source_name) values ('7c18f988-30c9-5345-abf5-06470db14b32', '0e475f9e-f9ab-5984-a4b7-711662f999f1', 'de', 'translation', 'Dein Herr hat sich weder von dir verabschiedet noch haßt Er (dich).', 'Frank Bubenheim and Nadeem (Quran.com)') on conflict (id) do nothing;
insert into entry_translations (id, entry_id, lang, kind, body, source_name) values ('41bf86cb-f144-58f7-a74e-4d45cfd19d22', '0e475f9e-f9ab-5984-a4b7-711662f999f1', 'en', 'translation', 'Your Lord has not taken leave of you, [O Muḥammad], nor has He detested [you].', 'Saheeh International (Quran.com)') on conflict (id) do nothing;
insert into entry_translations (id, entry_id, lang, kind, body, source_name) values ('46e33b76-69e4-5636-a87f-06c9486a72e9', '0e475f9e-f9ab-5984-a4b7-711662f999f1', 'ar', 'explanation', 'ربك ما خلاك وما كرهك، رحمتو كتبقى معاك.', null) on conflict (id) do nothing;
insert into entry_emotions (entry_id, emotion_id) values ('0e475f9e-f9ab-5984-a4b7-711662f999f1', '1de43123-dc44-5aea-ab96-c4a0dcff720d') on conflict do nothing;
insert into entry_emotions (entry_id, emotion_id) values ('0e475f9e-f9ab-5984-a4b7-711662f999f1', '803c63e3-df9a-5be1-a805-2b338c000ffb') on conflict do nothing;
insert into religious_entries (id, type, arabic_text, surah_number, surah_name_ar, surah_name_en, ayah_number, source_id, source_reference, source_url, audio_url, audio_source, status, source_verified, verified_at) values ('43d0cbb4-5e9b-5fc0-a90c-5cc3af804290', 'quran', 'وَلَسَوْفَ يُعْطِيكَ رَبُّكَ فَتَرْضَىٰٓ', 93, 'الضحى', 'Ad-Duhaa', 5, 'f88c713d-6666-5de8-ac4d-65e5f14fe111', '93:5', 'https://quran.com/93/5', 'https://verses.quran.com/Alafasy/mp3/093005.mp3', 'Quran.com (Mishari al-Afasy)', 'published', true, now()) on conflict (id) do nothing;
insert into entry_translations (id, entry_id, lang, kind, body, source_name) values ('87b58f5d-9596-5cff-a69e-f02fb89591fd', '43d0cbb4-5e9b-5fc0-a90c-5cc3af804290', 'de', 'translation', 'Und dein Herr wird dir wahrlich geben, und dann wirst du zufrieden sein.', 'Frank Bubenheim and Nadeem (Quran.com)') on conflict (id) do nothing;
insert into entry_translations (id, entry_id, lang, kind, body, source_name) values ('d40d5d1e-8743-5b24-aa23-c6b4b6734545', '43d0cbb4-5e9b-5fc0-a90c-5cc3af804290', 'en', 'translation', 'And your Lord is going to give you, and you will be satisfied.', 'Saheeh International (Quran.com)') on conflict (id) do nothing;
insert into entry_translations (id, entry_id, lang, kind, body, source_name) values ('4b47cafb-bc30-580d-a553-354192ede636', '43d0cbb4-5e9b-5fc0-a90c-5cc3af804290', 'ar', 'explanation', 'الله وعد بالعطاء حتى ترضى.', null) on conflict (id) do nothing;
insert into entry_emotions (entry_id, emotion_id) values ('43d0cbb4-5e9b-5fc0-a90c-5cc3af804290', 'a3404e43-045e-5417-ab4c-d23ba0286dbb') on conflict do nothing;
insert into entry_emotions (entry_id, emotion_id) values ('43d0cbb4-5e9b-5fc0-a90c-5cc3af804290', 'a745ea41-d3a7-5bc3-a25d-4524534d474e') on conflict do nothing;
insert into religious_entries (id, type, arabic_text, surah_number, surah_name_ar, surah_name_en, ayah_number, source_id, source_reference, source_url, audio_url, audio_source, status, source_verified, verified_at) values ('4213cc79-7dbf-5a07-aeba-cb02b63f859e', 'quran', 'قَالَ لَا تَخَافَآ ۖ إِنَّنِى مَعَكُمَآ أَسْمَعُ وَأَرَىٰ', 20, 'طه', 'Taha', 46, 'f88c713d-6666-5de8-ac4d-65e5f14fe111', '20:46', 'https://quran.com/20/46', 'https://verses.quran.com/Alafasy/mp3/020046.mp3', 'Quran.com (Mishari al-Afasy)', 'published', true, now()) on conflict (id) do nothing;
insert into entry_translations (id, entry_id, lang, kind, body, source_name) values ('d1737f2f-9340-549c-a41c-948f80f9217f', '4213cc79-7dbf-5a07-aeba-cb02b63f859e', 'de', 'translation', 'Er sagte: „Fürchtet euch nicht. Ich bin gewiß mit euch, Ich höre und Ich sehe (, was geschieht).', 'Frank Bubenheim and Nadeem (Quran.com)') on conflict (id) do nothing;
insert into entry_translations (id, entry_id, lang, kind, body, source_name) values ('fa9a74b0-864b-59ff-a7f5-f9ff44b1f9c2', '4213cc79-7dbf-5a07-aeba-cb02b63f859e', 'en', 'translation', '[Allāh] said, "Fear not. Indeed, I am with you both; I hear and I see.', 'Saheeh International (Quran.com)') on conflict (id) do nothing;
insert into entry_translations (id, entry_id, lang, kind, body, source_name) values ('403ff11d-f09d-5ec1-acb5-4062f1a0cfab', '4213cc79-7dbf-5a07-aeba-cb02b63f859e', 'ar', 'explanation', 'الله كيقول للي كيخاف: ما تخافش، أنا معاك كنسمع وكنشوف.', null) on conflict (id) do nothing;
insert into entry_emotions (entry_id, emotion_id) values ('4213cc79-7dbf-5a07-aeba-cb02b63f859e', '2328342b-26af-598e-afd4-ad07b2bf2997') on conflict do nothing;
insert into religious_entries (id, type, arabic_text, surah_number, surah_name_ar, surah_name_en, ayah_number, source_id, source_reference, source_url, audio_url, audio_source, status, source_verified, verified_at) values ('41be2505-5a81-58fb-a531-bde503556216', 'quran', 'ٱلَّذِينَ قَالَ لَهُمُ ٱلنَّاسُ إِنَّ ٱلنَّاسَ قَدْ جَمَعُوا۟ لَكُمْ فَٱخْشَوْهُمْ فَزَادَهُمْ إِيمَـٰنًا وَقَالُوا۟ حَسْبُنَا ٱللَّهُ وَنِعْمَ ٱلْوَكِيلُ', 3, 'آل عمران', 'Ali ''Imran', 173, 'f88c713d-6666-5de8-ac4d-65e5f14fe111', '3:173', 'https://quran.com/3/173', 'https://verses.quran.com/Alafasy/mp3/003173.mp3', 'Quran.com (Mishari al-Afasy)', 'published', true, now()) on conflict (id) do nothing;
insert into entry_translations (id, entry_id, lang, kind, body, source_name) values ('5746086d-0f71-50db-aaac-8ea0e669047c', '41be2505-5a81-58fb-a531-bde503556216', 'de', 'translation', 'Diejenigen, zu denen die Menschen sagten: „Die Menschen haben (sich) bereits gegen euch versammelt; darum fürchtet sie! - Doch da mehrte das (nur) ihren Glauben, und sie sagten: „Unsere Genüge ist Allah, und wie trefflich ist der Sachwalter!', 'Frank Bubenheim and Nadeem (Quran.com)') on conflict (id) do nothing;
insert into entry_translations (id, entry_id, lang, kind, body, source_name) values ('7af121b3-57a2-566f-a49c-a7fbd200a3ab', '41be2505-5a81-58fb-a531-bde503556216', 'en', 'translation', 'Those to whom people [i.e., hypocrites] said, "Indeed, the people have gathered against you, so fear them." But it [merely] increased them in faith, and they said, "Sufficient for us is Allāh, and [He is] the best Disposer of affairs."', 'Saheeh International (Quran.com)') on conflict (id) do nothing;
insert into entry_translations (id, entry_id, lang, kind, body, source_name) values ('e13c57f6-e33d-5b1c-a275-52691970da50', '41be2505-5a81-58fb-a531-bde503556216', 'ar', 'explanation', 'فوقت الخوف، التوكل على الله هو الملجأ.', null) on conflict (id) do nothing;
insert into entry_emotions (entry_id, emotion_id) values ('41be2505-5a81-58fb-a531-bde503556216', '2328342b-26af-598e-afd4-ad07b2bf2997') on conflict do nothing;
insert into entry_emotions (entry_id, emotion_id) values ('41be2505-5a81-58fb-a531-bde503556216', '8dde18d5-b9b7-5e14-a037-21ab395074c1') on conflict do nothing;
insert into religious_entries (id, type, arabic_text, surah_number, surah_name_ar, surah_name_en, ayah_number, source_id, source_reference, source_url, audio_url, audio_source, status, source_verified, verified_at) values ('d1d244c0-e0ce-5e4b-a613-84e9c3bc67f0', 'quran', '۞ قُلْ يَـٰعِبَادِىَ ٱلَّذِينَ أَسْرَفُوا۟ عَلَىٰٓ أَنفُسِهِمْ لَا تَقْنَطُوا۟ مِن رَّحْمَةِ ٱللَّهِ ۚ إِنَّ ٱللَّهَ يَغْفِرُ ٱلذُّنُوبَ جَمِيعًا ۚ إِنَّهُۥ هُوَ ٱلْغَفُورُ ٱلرَّحِيمُ', 39, 'الزمر', 'Az-Zumar', 53, 'f88c713d-6666-5de8-ac4d-65e5f14fe111', '39:53', 'https://quran.com/39/53', 'https://verses.quran.com/Alafasy/mp3/039053.mp3', 'Quran.com (Mishari al-Afasy)', 'published', true, now()) on conflict (id) do nothing;
insert into entry_translations (id, entry_id, lang, kind, body, source_name) values ('791e2c54-642c-5ab5-af8c-ad13cb5ba433', 'd1d244c0-e0ce-5e4b-a613-84e9c3bc67f0', 'de', 'translation', 'Sag: O Meine Diener, die ihr gegen euch selbst maßlos gewesen seid, verliert nicht die Hoffnung auf Allahs Barmherzigkeit. Gewiß, Allah vergibt die Sünden alle. Er ist ja der Allvergebende und Barmherzige.', 'Frank Bubenheim and Nadeem (Quran.com)') on conflict (id) do nothing;
insert into entry_translations (id, entry_id, lang, kind, body, source_name) values ('0626bbd2-e524-5e14-ad86-013bd5d4ec55', 'd1d244c0-e0ce-5e4b-a613-84e9c3bc67f0', 'en', 'translation', 'Say, "O My servants who have transgressed against themselves [by sinning], do not despair of the mercy of Allāh. Indeed, Allāh forgives all sins. Indeed, it is He who is the Forgiving, the Merciful."', 'Saheeh International (Quran.com)') on conflict (id) do nothing;
insert into entry_translations (id, entry_id, lang, kind, body, source_name) values ('a70556ed-3d0e-5188-aed6-42af144e1087', 'd1d244c0-e0ce-5e4b-a613-84e9c3bc67f0', 'ar', 'explanation', 'باب رحمة الله مفتوح، ما تيأسش مهما كانو الذنوب.', null) on conflict (id) do nothing;
insert into entry_emotions (entry_id, emotion_id) values ('d1d244c0-e0ce-5e4b-a613-84e9c3bc67f0', 'f5632603-02f9-5df9-aed0-619f83563bd1') on conflict do nothing;
insert into entry_emotions (entry_id, emotion_id) values ('d1d244c0-e0ce-5e4b-a613-84e9c3bc67f0', 'a745ea41-d3a7-5bc3-a25d-4524534d474e') on conflict do nothing;
insert into religious_entries (id, type, arabic_text, surah_number, surah_name_ar, surah_name_en, ayah_number, source_id, source_reference, source_url, audio_url, audio_source, status, source_verified, verified_at) values ('64dbdabf-847e-5ad3-ab37-8eb553471f0b', 'quran', 'إِلَّا مَن تَابَ وَءَامَنَ وَعَمِلَ عَمَلًا صَـٰلِحًا فَأُو۟لَـٰٓئِكَ يُبَدِّلُ ٱللَّهُ سَيِّـَٔاتِهِمْ حَسَنَـٰتٍ ۗ وَكَانَ ٱللَّهُ غَفُورًا رَّحِيمًا', 25, 'الفرقان', 'Al-Furqan', 70, 'f88c713d-6666-5de8-ac4d-65e5f14fe111', '25:70', 'https://quran.com/25/70', 'https://verses.quran.com/Alafasy/mp3/025070.mp3', 'Quran.com (Mishari al-Afasy)', 'published', true, now()) on conflict (id) do nothing;
insert into entry_translations (id, entry_id, lang, kind, body, source_name) values ('be04c649-67ed-50fa-a86a-8033a98b1c8c', '64dbdabf-847e-5ad3-ab37-8eb553471f0b', 'de', 'translation', 'außer demjenigen, der bereut, glaubt und rechtschaffene Werke tut; jenen wird Allah ihre bösen Taten gegen gute eintauschen; und Allah ist stets Allvergebend und Barmherzig.', 'Frank Bubenheim and Nadeem (Quran.com)') on conflict (id) do nothing;
insert into entry_translations (id, entry_id, lang, kind, body, source_name) values ('94e5d09e-7662-5411-a6a0-b7c8cfcf0efe', '64dbdabf-847e-5ad3-ab37-8eb553471f0b', 'en', 'translation', 'Except for those who repent, believe and do righteous work. For them Allāh will replace their evil deeds with good. And ever is Allāh Forgiving and Merciful.', 'Saheeh International (Quran.com)') on conflict (id) do nothing;
insert into entry_translations (id, entry_id, lang, kind, body, source_name) values ('00773298-fa72-5859-a46a-b9a77523145d', '64dbdabf-847e-5ad3-ab37-8eb553471f0b', 'ar', 'explanation', 'التوبة الصادقة والعمل الصالح كيفتحو باب الرحمة.', null) on conflict (id) do nothing;
insert into entry_emotions (entry_id, emotion_id) values ('64dbdabf-847e-5ad3-ab37-8eb553471f0b', 'f5632603-02f9-5df9-aed0-619f83563bd1') on conflict do nothing;
insert into religious_entries (id, type, arabic_text, surah_number, surah_name_ar, surah_name_en, ayah_number, source_id, source_reference, source_url, audio_url, audio_source, status, source_verified, verified_at) values ('db53f133-3be2-5828-a0dd-e6c643675243', 'quran', 'وَيَسْـَٔلُونَكَ عَنِ ٱلْمَحِيضِ ۖ قُلْ هُوَ أَذًى فَٱعْتَزِلُوا۟ ٱلنِّسَآءَ فِى ٱلْمَحِيضِ ۖ وَلَا تَقْرَبُوهُنَّ حَتَّىٰ يَطْهُرْنَ ۖ فَإِذَا تَطَهَّرْنَ فَأْتُوهُنَّ مِنْ حَيْثُ أَمَرَكُمُ ٱللَّهُ ۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلتَّوَّٰبِينَ وَيُحِبُّ ٱلْمُتَطَهِّرِينَ', 2, 'البقرة', 'Al-Baqarah', 222, 'f88c713d-6666-5de8-ac4d-65e5f14fe111', '2:222', 'https://quran.com/2/222', 'https://verses.quran.com/Alafasy/mp3/002222.mp3', 'Quran.com (Mishari al-Afasy)', 'published', true, now()) on conflict (id) do nothing;
insert into entry_translations (id, entry_id, lang, kind, body, source_name) values ('6206ac04-f2ee-5205-a0b0-34c48c2b4930', 'db53f133-3be2-5828-a0dd-e6c643675243', 'de', 'translation', 'Sie fragen dich nach der Monatsblutung. Sag: Sie ist ein Leiden. So haltet euch von den Frauen während der Monatsblutung fern, und kommt ihnen nicht nahe, bis sie rein sind. Wenn sie sich dann gereinigt haben, so kommt zu ihnen, wie Allah es euch geboten hat. Allah liebt die Reumütigen, und Er liebt die, die sich rein halten.', 'Frank Bubenheim and Nadeem (Quran.com)') on conflict (id) do nothing;
insert into entry_translations (id, entry_id, lang, kind, body, source_name) values ('9892890f-4d29-5ee7-a419-bfeedc6a198e', 'db53f133-3be2-5828-a0dd-e6c643675243', 'en', 'translation', 'And they ask you about menstruation. Say, "It is harm, so keep away from wives during menstruation. And do not approach them until they are pure. And when they have purified themselves, then come to them from where Allāh has ordained for you. Indeed, Allāh loves those who are constantly repentant and loves those who purify themselves."', 'Saheeh International (Quran.com)') on conflict (id) do nothing;
insert into entry_translations (id, entry_id, lang, kind, body, source_name) values ('172a95df-d084-5c4b-abca-e1f002015b47', 'db53f133-3be2-5828-a0dd-e6c643675243', 'ar', 'explanation', 'الله كيحب اللي كيرجع ليه بالتوبة.', null) on conflict (id) do nothing;
insert into entry_emotions (entry_id, emotion_id) values ('db53f133-3be2-5828-a0dd-e6c643675243', 'f5632603-02f9-5df9-aed0-619f83563bd1') on conflict do nothing;
insert into religious_entries (id, type, arabic_text, surah_number, surah_name_ar, surah_name_en, ayah_number, source_id, source_reference, source_url, audio_url, audio_source, status, source_verified, verified_at) values ('5f773e1f-5b31-524c-a552-8b6844f83d04', 'quran', 'وَإِذْ تَأَذَّنَ رَبُّكُمْ لَئِن شَكَرْتُمْ لَأَزِيدَنَّكُمْ ۖ وَلَئِن كَفَرْتُمْ إِنَّ عَذَابِى لَشَدِيدٌ', 14, 'ابراهيم', 'Ibrahim', 7, 'f88c713d-6666-5de8-ac4d-65e5f14fe111', '14:7', 'https://quran.com/14/7', 'https://verses.quran.com/Alafasy/mp3/014007.mp3', 'Quran.com (Mishari al-Afasy)', 'published', true, now()) on conflict (id) do nothing;
insert into entry_translations (id, entry_id, lang, kind, body, source_name) values ('f835bf81-5385-5e39-a50f-7022fd8d86df', '5f773e1f-5b31-524c-a552-8b6844f83d04', 'de', 'translation', 'Und als euer Herr ankündigte: ,Wenn ihr dankbar seid, werde Ich euch ganz gewiß noch mehr (Gunst) erweisen. Wenn ihr jedoch undankbar seid, dann ist meine Strafe fürwahr streng.', 'Frank Bubenheim and Nadeem (Quran.com)') on conflict (id) do nothing;
insert into entry_translations (id, entry_id, lang, kind, body, source_name) values ('8df60349-6fbd-5284-a4ef-9059c438e317', '5f773e1f-5b31-524c-a552-8b6844f83d04', 'en', 'translation', 'And [remember] when your Lord proclaimed, ''If you are grateful, I will surely increase you [in favor]; but if you deny, indeed, My punishment is severe.''"', 'Saheeh International (Quran.com)') on conflict (id) do nothing;
insert into entry_translations (id, entry_id, lang, kind, body, source_name) values ('329b876e-5a9a-5ad3-a2b9-fa42d60894fe', '5f773e1f-5b31-524c-a552-8b6844f83d04', 'ar', 'explanation', 'الشكر كيزيد النعمة ويقرب القلب من الله.', null) on conflict (id) do nothing;
insert into entry_emotions (entry_id, emotion_id) values ('5f773e1f-5b31-524c-a552-8b6844f83d04', '0296e2ef-96c0-5d63-a57e-4cf00252b71e') on conflict do nothing;
insert into religious_entries (id, type, arabic_text, surah_number, surah_name_ar, surah_name_en, ayah_number, source_id, source_reference, source_url, audio_url, audio_source, status, source_verified, verified_at) values ('b3b5da09-53ad-50fd-a151-302bed8fb711', 'quran', 'فَٱذْكُرُونِىٓ أَذْكُرْكُمْ وَٱشْكُرُوا۟ لِى وَلَا تَكْفُرُونِ', 2, 'البقرة', 'Al-Baqarah', 152, 'f88c713d-6666-5de8-ac4d-65e5f14fe111', '2:152', 'https://quran.com/2/152', 'https://verses.quran.com/Alafasy/mp3/002152.mp3', 'Quran.com (Mishari al-Afasy)', 'published', true, now()) on conflict (id) do nothing;
insert into entry_translations (id, entry_id, lang, kind, body, source_name) values ('a75d8b3f-ae33-5d03-ad8a-45bbc7a962e9', 'b3b5da09-53ad-50fd-a151-302bed8fb711', 'de', 'translation', 'Gedenkt Meiner, so gedenke Ich eurer. Seid Mir dankbar und seid nicht undankbar gegen Mich.', 'Frank Bubenheim and Nadeem (Quran.com)') on conflict (id) do nothing;
insert into entry_translations (id, entry_id, lang, kind, body, source_name) values ('52341953-197a-5d0a-aaa8-c979e10cdac6', 'b3b5da09-53ad-50fd-a151-302bed8fb711', 'en', 'translation', 'So remember Me; I will remember you. And be grateful to Me and do not deny Me.', 'Saheeh International (Quran.com)') on conflict (id) do nothing;
insert into entry_translations (id, entry_id, lang, kind, body, source_name) values ('c03e2324-00c5-5b31-aeab-94b894852913', 'b3b5da09-53ad-50fd-a151-302bed8fb711', 'ar', 'explanation', 'ملي كنذكرو الله، هو كيذكرنا. ما كنتيناش بوحدنا.', null) on conflict (id) do nothing;
insert into entry_emotions (entry_id, emotion_id) values ('b3b5da09-53ad-50fd-a151-302bed8fb711', '0296e2ef-96c0-5d63-a57e-4cf00252b71e') on conflict do nothing;
insert into entry_emotions (entry_id, emotion_id) values ('b3b5da09-53ad-50fd-a151-302bed8fb711', '803c63e3-df9a-5be1-a805-2b338c000ffb') on conflict do nothing;
insert into religious_entries (id, type, arabic_text, surah_number, surah_name_ar, surah_name_en, ayah_number, source_id, source_reference, source_url, audio_url, audio_source, status, source_verified, verified_at) values ('20d72a59-8b18-596d-a8f8-b1be7675b404', 'quran', 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 55, 'الرحمن', 'Ar-Rahman', 13, 'f88c713d-6666-5de8-ac4d-65e5f14fe111', '55:13', 'https://quran.com/55/13', 'https://verses.quran.com/Alafasy/mp3/055013.mp3', 'Quran.com (Mishari al-Afasy)', 'published', true, now()) on conflict (id) do nothing;
insert into entry_translations (id, entry_id, lang, kind, body, source_name) values ('7d086993-f187-5b54-a42c-ef429223e7e1', '20d72a59-8b18-596d-a8f8-b1be7675b404', 'de', 'translation', 'Welche der Wohltaten eures Herrn wollt ihr beide denn leugnen?', 'Frank Bubenheim and Nadeem (Quran.com)') on conflict (id) do nothing;
insert into entry_translations (id, entry_id, lang, kind, body, source_name) values ('af38062b-f5e3-524e-a7c5-c90bfc3bf359', '20d72a59-8b18-596d-a8f8-b1be7675b404', 'en', 'translation', 'So which of the favors of your Lord would you deny?', 'Saheeh International (Quran.com)') on conflict (id) do nothing;
insert into entry_translations (id, entry_id, lang, kind, body, source_name) values ('345b55cc-abe5-5e1e-af38-78ef5ac9f6e6', '20d72a59-8b18-596d-a8f8-b1be7675b404', 'ar', 'explanation', 'نعم الله بزاف، وكل وحدة فيها تذكير بالشكر.', null) on conflict (id) do nothing;
insert into entry_emotions (entry_id, emotion_id) values ('20d72a59-8b18-596d-a8f8-b1be7675b404', '0296e2ef-96c0-5d63-a57e-4cf00252b71e') on conflict do nothing;
insert into religious_entries (id, type, arabic_text, surah_number, surah_name_ar, surah_name_en, ayah_number, source_id, source_reference, source_url, audio_url, audio_source, status, source_verified, verified_at) values ('62b14f36-7ac7-5414-ace6-fb268eb846dc', 'quran', 'وَيَرْزُقْهُ مِنْ حَيْثُ لَا يَحْتَسِبُ ۚ وَمَن يَتَوَكَّلْ عَلَى ٱللَّهِ فَهُوَ حَسْبُهُۥٓ ۚ إِنَّ ٱللَّهَ بَـٰلِغُ أَمْرِهِۦ ۚ قَدْ جَعَلَ ٱللَّهُ لِكُلِّ شَىْءٍ قَدْرًا', 65, 'الطلاق', 'At-Talaq', 3, 'f88c713d-6666-5de8-ac4d-65e5f14fe111', '65:3', 'https://quran.com/65/3', 'https://verses.quran.com/Alafasy/mp3/065003.mp3', 'Quran.com (Mishari al-Afasy)', 'published', true, now()) on conflict (id) do nothing;
insert into entry_translations (id, entry_id, lang, kind, body, source_name) values ('3a3b4f47-bbcc-5f5c-a26d-ea0edaab1657', '62b14f36-7ac7-5414-ace6-fb268eb846dc', 'de', 'translation', 'und gewährt ihm Versorgung, von wo (aus) er damit nicht rechnet. Und wer sich auf Allah verläßt, dem ist Er seine Genüge. Allah wird gewiß (die Durchführung) seine(r) Angelegenheit erreichen. Allah legt ja für alles ein Maß fest.', 'Frank Bubenheim and Nadeem (Quran.com)') on conflict (id) do nothing;
insert into entry_translations (id, entry_id, lang, kind, body, source_name) values ('22f62410-162e-58ff-aa50-66ca87b45027', '62b14f36-7ac7-5414-ace6-fb268eb846dc', 'en', 'translation', 'And will provide for him from where he does not expect. And whoever relies upon Allāh - then He is sufficient for him. Indeed, Allāh will accomplish His purpose. Allāh has already set for everything a [decreed] extent.', 'Saheeh International (Quran.com)') on conflict (id) do nothing;
insert into entry_translations (id, entry_id, lang, kind, body, source_name) values ('2ce6e9e9-decf-505c-a5fd-57b072bb7b0d', '62b14f36-7ac7-5414-ace6-fb268eb846dc', 'ar', 'explanation', 'اللي كيتوكل على الله، الله كافيه.', null) on conflict (id) do nothing;
insert into entry_emotions (entry_id, emotion_id) values ('62b14f36-7ac7-5414-ace6-fb268eb846dc', '8dde18d5-b9b7-5e14-a037-21ab395074c1') on conflict do nothing;
insert into entry_emotions (entry_id, emotion_id) values ('62b14f36-7ac7-5414-ace6-fb268eb846dc', 'f66ac991-0301-508c-af43-5b31e3293d2d') on conflict do nothing;
insert into religious_entries (id, type, arabic_text, surah_number, surah_name_ar, surah_name_en, ayah_number, source_id, source_reference, source_url, audio_url, audio_source, status, source_verified, verified_at) values ('fb787730-4ea2-52b7-afe1-1bc149a53150', 'quran', 'قَالَ رَبِّ ٱشْرَحْ لِى صَدْرِى', 20, 'طه', 'Taha', 25, 'f88c713d-6666-5de8-ac4d-65e5f14fe111', '20:25', 'https://quran.com/20/25', 'https://verses.quran.com/Alafasy/mp3/020025.mp3', 'Quran.com (Mishari al-Afasy)', 'published', true, now()) on conflict (id) do nothing;
insert into entry_translations (id, entry_id, lang, kind, body, source_name) values ('83ae440c-6bd2-5a46-aab1-240b907b6eb5', 'fb787730-4ea2-52b7-afe1-1bc149a53150', 'de', 'translation', 'Er sagte: „Mein Herr, weite mir meine Brust,', 'Frank Bubenheim and Nadeem (Quran.com)') on conflict (id) do nothing;
insert into entry_translations (id, entry_id, lang, kind, body, source_name) values ('958f0361-2cfe-5dd6-acfb-50d227cd0a86', 'fb787730-4ea2-52b7-afe1-1bc149a53150', 'en', 'translation', '[Moses] said, "My Lord, expand [i.e., relax] for me my breast [with assurance]', 'Saheeh International (Quran.com)') on conflict (id) do nothing;
insert into entry_translations (id, entry_id, lang, kind, body, source_name) values ('4d41cc48-47ff-599e-abdd-48b4e17105e1', 'fb787730-4ea2-52b7-afe1-1bc149a53150', 'ar', 'explanation', 'دعاء بسيط ديال سيدنا موسى: يا رب وسع ليا صدري.', null) on conflict (id) do nothing;
insert into entry_emotions (entry_id, emotion_id) values ('fb787730-4ea2-52b7-afe1-1bc149a53150', '8dde18d5-b9b7-5e14-a037-21ab395074c1') on conflict do nothing;
insert into entry_emotions (entry_id, emotion_id) values ('fb787730-4ea2-52b7-afe1-1bc149a53150', 'd7c0cea5-0d24-5079-a891-0600fda15645') on conflict do nothing;
insert into religious_entries (id, type, arabic_text, surah_number, surah_name_ar, surah_name_en, ayah_number, source_id, source_reference, source_url, audio_url, audio_source, status, source_verified, verified_at) values ('09f821d5-4766-58c8-aca4-f29cfcd51ca5', 'quran', 'ٱلَّذِينَ يُنفِقُونَ فِى ٱلسَّرَّآءِ وَٱلضَّرَّآءِ وَٱلْكَـٰظِمِينَ ٱلْغَيْظَ وَٱلْعَافِينَ عَنِ ٱلنَّاسِ ۗ وَٱللَّهُ يُحِبُّ ٱلْمُحْسِنِينَ', 3, 'آل عمران', 'Ali ''Imran', 134, 'f88c713d-6666-5de8-ac4d-65e5f14fe111', '3:134', 'https://quran.com/3/134', 'https://verses.quran.com/Alafasy/mp3/003134.mp3', 'Quran.com (Mishari al-Afasy)', 'published', true, now()) on conflict (id) do nothing;
insert into entry_translations (id, entry_id, lang, kind, body, source_name) values ('f77c5ab5-f4e4-5122-a6ae-643745224995', '09f821d5-4766-58c8-aca4-f29cfcd51ca5', 'de', 'translation', 'die in Freude und Leid ausgeben und ihren Grimm zurückhalten und den Menschen verzeihen. Und Allah liebt die Gutes Tuenden', 'Frank Bubenheim and Nadeem (Quran.com)') on conflict (id) do nothing;
insert into entry_translations (id, entry_id, lang, kind, body, source_name) values ('98eebec0-1456-510b-a09e-ee320b5ee7ff', '09f821d5-4766-58c8-aca4-f29cfcd51ca5', 'en', 'translation', 'Who spend [in the cause of Allāh] during ease and hardship and who restrain anger and who pardon the people - and Allāh loves the doers of good;', 'Saheeh International (Quran.com)') on conflict (id) do nothing;
insert into entry_translations (id, entry_id, lang, kind, body, source_name) values ('c5ace410-f4dd-59ba-a3b2-221f4af36630', '09f821d5-4766-58c8-aca4-f29cfcd51ca5', 'ar', 'explanation', 'كظم الغيظ والعفو على الناس من صفات المحسنين.', null) on conflict (id) do nothing;
insert into entry_emotions (entry_id, emotion_id) values ('09f821d5-4766-58c8-aca4-f29cfcd51ca5', 'a8d0ff7c-240b-5999-a8b5-f694608a1c91') on conflict do nothing;
insert into religious_entries (id, type, arabic_text, surah_number, surah_name_ar, surah_name_en, ayah_number, source_id, source_reference, source_url, audio_url, audio_source, status, source_verified, verified_at) values ('1b6f355b-6b90-583c-abaa-29e77568bcd7', 'quran', 'وَلَا تَسْتَوِى ٱلْحَسَنَةُ وَلَا ٱلسَّيِّئَةُ ۚ ٱدْفَعْ بِٱلَّتِى هِىَ أَحْسَنُ فَإِذَا ٱلَّذِى بَيْنَكَ وَبَيْنَهُۥ عَدَٰوَةٌ كَأَنَّهُۥ وَلِىٌّ حَمِيمٌ', 41, 'فصلت', 'Fussilat', 34, 'f88c713d-6666-5de8-ac4d-65e5f14fe111', '41:34', 'https://quran.com/41/34', 'https://verses.quran.com/Alafasy/mp3/041034.mp3', 'Quran.com (Mishari al-Afasy)', 'published', true, now()) on conflict (id) do nothing;
insert into entry_translations (id, entry_id, lang, kind, body, source_name) values ('517c2c13-dbdc-5ff9-ad40-eac7c2b9f7ef', '1b6f355b-6b90-583c-abaa-29e77568bcd7', 'de', 'translation', 'Nicht gleich sind die gute Tat und die schlechte Tat. Wehre mit einer Tat, die besser ist, (die schlechte) ab, dann wird derjenige, zwischen dem und dir Feindschaft besteht, so, als wäre er ein warmherziger Freund.', 'Frank Bubenheim and Nadeem (Quran.com)') on conflict (id) do nothing;
insert into entry_translations (id, entry_id, lang, kind, body, source_name) values ('5fc65b89-dbe2-5c7c-ac23-7855561e7091', '1b6f355b-6b90-583c-abaa-29e77568bcd7', 'en', 'translation', 'And not equal are the good deed and the bad. Repel [evil] by that [deed] which is better; and thereupon, the one whom between you and him is enmity [will become] as though he was a devoted friend.', 'Saheeh International (Quran.com)') on conflict (id) do nothing;
insert into entry_translations (id, entry_id, lang, kind, body, source_name) values ('d1ee451e-f7db-562a-a86d-fba395713f92', '1b6f355b-6b90-583c-abaa-29e77568bcd7', 'ar', 'explanation', 'رد على الإساءة بالأحسن، وكتلقى القلوب كتتبدل.', null) on conflict (id) do nothing;
insert into entry_emotions (entry_id, emotion_id) values ('1b6f355b-6b90-583c-abaa-29e77568bcd7', 'a8d0ff7c-240b-5999-a8b5-f694608a1c91') on conflict do nothing;
insert into religious_entries (id, type, arabic_text, surah_number, surah_name_ar, surah_name_en, ayah_number, source_id, source_reference, source_url, audio_url, audio_source, status, source_verified, verified_at) values ('f34a9afb-5e4a-50c4-a9a4-2086086b3624', 'quran', 'قُلْ بِفَضْلِ ٱللَّهِ وَبِرَحْمَتِهِۦ فَبِذَٰلِكَ فَلْيَفْرَحُوا۟ هُوَ خَيْرٌ مِّمَّا يَجْمَعُونَ', 10, 'يونس', 'Yunus', 58, 'f88c713d-6666-5de8-ac4d-65e5f14fe111', '10:58', 'https://quran.com/10/58', 'https://verses.quran.com/Alafasy/mp3/010058.mp3', 'Quran.com (Mishari al-Afasy)', 'published', true, now()) on conflict (id) do nothing;
insert into entry_translations (id, entry_id, lang, kind, body, source_name) values ('02b93142-be35-5aa8-ab22-f3e337b579ee', 'f34a9afb-5e4a-50c4-a9a4-2086086b3624', 'de', 'translation', 'Sag: Über die Huld Allahs und über Seine Barmherzigkeit, ja darüber sollen sie froh sein. Das ist besser als das, was sie zusammentragen.', 'Frank Bubenheim and Nadeem (Quran.com)') on conflict (id) do nothing;
insert into entry_translations (id, entry_id, lang, kind, body, source_name) values ('39327a71-9da5-5474-a2e2-eaa16adcc469', 'f34a9afb-5e4a-50c4-a9a4-2086086b3624', 'en', 'translation', 'Say, "In the bounty of Allāh and in His mercy - in that let them rejoice; it is better than what they accumulate."', 'Saheeh International (Quran.com)') on conflict (id) do nothing;
insert into entry_translations (id, entry_id, lang, kind, body, source_name) values ('6ed0307b-5f84-5de6-acbc-91de97ed00d4', 'f34a9afb-5e4a-50c4-a9a4-2086086b3624', 'ar', 'explanation', 'الفرح الحقيقي هو الفرح بفضل الله ورحمتو.', null) on conflict (id) do nothing;
insert into entry_emotions (entry_id, emotion_id) values ('f34a9afb-5e4a-50c4-a9a4-2086086b3624', 'a3404e43-045e-5417-ab4c-d23ba0286dbb') on conflict do nothing;
insert into religious_entries (id, type, arabic_text, surah_number, surah_name_ar, surah_name_en, ayah_number, source_id, source_reference, source_url, audio_url, audio_source, status, source_verified, verified_at) values ('ea43a8bf-01b3-58c8-a68e-0055c85cf473', 'quran', 'وَإِذَا سَأَلَكَ عِبَادِى عَنِّى فَإِنِّى قَرِيبٌ ۖ أُجِيبُ دَعْوَةَ ٱلدَّاعِ إِذَا دَعَانِ ۖ فَلْيَسْتَجِيبُوا۟ لِى وَلْيُؤْمِنُوا۟ بِى لَعَلَّهُمْ يَرْشُدُونَ', 2, 'البقرة', 'Al-Baqarah', 186, 'f88c713d-6666-5de8-ac4d-65e5f14fe111', '2:186', 'https://quran.com/2/186', 'https://verses.quran.com/Alafasy/mp3/002186.mp3', 'Quran.com (Mishari al-Afasy)', 'published', true, now()) on conflict (id) do nothing;
insert into entry_translations (id, entry_id, lang, kind, body, source_name) values ('e318dc9e-2b48-541f-a2ce-82a8f3664f0b', 'ea43a8bf-01b3-58c8-a68e-0055c85cf473', 'de', 'translation', 'Und wenn dich Meine Diener nach Mir fragen, so bin Ich nahe; Ich erhöre den Ruf des Bittenden, wenn er Mich anruft. So sollen sie nun auf Mich hören und an Mich glauben, auf daß sie besonnen handeln mögen.', 'Frank Bubenheim and Nadeem (Quran.com)') on conflict (id) do nothing;
insert into entry_translations (id, entry_id, lang, kind, body, source_name) values ('b62051eb-a3f0-5eee-a535-635683cc2264', 'ea43a8bf-01b3-58c8-a68e-0055c85cf473', 'en', 'translation', 'And when My servants ask you, [O Muḥammad], concerning Me - indeed I am near. I respond to the invocation of the supplicant when he calls upon Me. So let them respond to Me [by obedience] and believe in Me that they may be [rightly] guided.', 'Saheeh International (Quran.com)') on conflict (id) do nothing;
insert into entry_translations (id, entry_id, lang, kind, body, source_name) values ('d3c48331-5a3d-5b53-aa09-3ebdaeb128ab', 'ea43a8bf-01b3-58c8-a68e-0055c85cf473', 'ar', 'explanation', 'الله قريب وكيجاوب على دعوة اللي دعاه.', null) on conflict (id) do nothing;
insert into entry_emotions (entry_id, emotion_id) values ('ea43a8bf-01b3-58c8-a68e-0055c85cf473', '803c63e3-df9a-5be1-a805-2b338c000ffb') on conflict do nothing;
insert into entry_emotions (entry_id, emotion_id) values ('ea43a8bf-01b3-58c8-a68e-0055c85cf473', 'a745ea41-d3a7-5bc3-a25d-4524534d474e') on conflict do nothing;
insert into religious_entries (id, type, arabic_text, surah_number, surah_name_ar, surah_name_en, ayah_number, source_id, source_reference, source_url, audio_url, audio_source, status, source_verified, verified_at) values ('464549ff-65ae-552e-a9b6-0e1fc43eda1a', 'quran', 'وَلَقَدْ خَلَقْنَا ٱلْإِنسَـٰنَ وَنَعْلَمُ مَا تُوَسْوِسُ بِهِۦ نَفْسُهُۥ ۖ وَنَحْنُ أَقْرَبُ إِلَيْهِ مِنْ حَبْلِ ٱلْوَرِيدِ', 50, 'ق', 'Qaf', 16, 'f88c713d-6666-5de8-ac4d-65e5f14fe111', '50:16', 'https://quran.com/50/16', 'https://verses.quran.com/Alafasy/mp3/050016.mp3', 'Quran.com (Mishari al-Afasy)', 'published', true, now()) on conflict (id) do nothing;
insert into entry_translations (id, entry_id, lang, kind, body, source_name) values ('df283f46-3ad1-5f46-ab77-fe5bef4ddc29', '464549ff-65ae-552e-a9b6-0e1fc43eda1a', 'de', 'translation', 'Wir haben ja den Menschen erschaffen und wissen, was (alles ihm) seine Seele einflüstert, und Wir sind ihm doch näher als seine Halsschlagader,', 'Frank Bubenheim and Nadeem (Quran.com)') on conflict (id) do nothing;
insert into entry_translations (id, entry_id, lang, kind, body, source_name) values ('51896446-575f-59b7-a6a2-92966f33806f', '464549ff-65ae-552e-a9b6-0e1fc43eda1a', 'en', 'translation', 'And We have already created man and know what his soul whispers to him, and We are closer to him than [his] jugular vein.', 'Saheeh International (Quran.com)') on conflict (id) do nothing;
insert into entry_translations (id, entry_id, lang, kind, body, source_name) values ('afca9182-ffca-5931-a339-2408ab5e25ff', '464549ff-65ae-552e-a9b6-0e1fc43eda1a', 'ar', 'explanation', 'الله قريب من الإنسان أكثر مما يتصور.', null) on conflict (id) do nothing;
insert into entry_emotions (entry_id, emotion_id) values ('464549ff-65ae-552e-a9b6-0e1fc43eda1a', '803c63e3-df9a-5be1-a805-2b338c000ffb') on conflict do nothing;
insert into religious_entries (id, type, arabic_text, surah_number, surah_name_ar, surah_name_en, ayah_number, source_id, source_reference, source_url, audio_url, audio_source, status, source_verified, verified_at) values ('9d5faba3-8a01-5389-aa5d-0187e7d41bbb', 'quran', 'وَٱصْبِرْ فَإِنَّ ٱللَّهَ لَا يُضِيعُ أَجْرَ ٱلْمُحْسِنِينَ', 11, 'هود', 'Hud', 115, 'f88c713d-6666-5de8-ac4d-65e5f14fe111', '11:115', 'https://quran.com/11/115', 'https://verses.quran.com/Alafasy/mp3/011115.mp3', 'Quran.com (Mishari al-Afasy)', 'published', true, now()) on conflict (id) do nothing;
insert into entry_translations (id, entry_id, lang, kind, body, source_name) values ('324afb1c-6044-55da-af2c-b47537ee949d', '9d5faba3-8a01-5389-aa5d-0187e7d41bbb', 'de', 'translation', 'Und sei standhaft; denn Allah läßt den Lohn der Gutes Tuenden nicht verlorengehen.', 'Frank Bubenheim and Nadeem (Quran.com)') on conflict (id) do nothing;
insert into entry_translations (id, entry_id, lang, kind, body, source_name) values ('2123a23e-743d-5052-a930-a352d0e28398', '9d5faba3-8a01-5389-aa5d-0187e7d41bbb', 'en', 'translation', 'And be patient, for indeed, Allāh does not allow to be lost the reward of those who do good.', 'Saheeh International (Quran.com)') on conflict (id) do nothing;
insert into entry_translations (id, entry_id, lang, kind, body, source_name) values ('f9aae954-649a-5b7e-aabc-53e7d4c1ea47', '9d5faba3-8a01-5389-aa5d-0187e7d41bbb', 'ar', 'explanation', 'اصبر، لأن الله ما كيضيع أجر المحسنين.', null) on conflict (id) do nothing;
insert into entry_emotions (entry_id, emotion_id) values ('9d5faba3-8a01-5389-aa5d-0187e7d41bbb', '53cf081d-6a36-5e2d-a534-6f958407bd76') on conflict do nothing;
insert into religious_entries (id, type, arabic_text, surah_number, surah_name_ar, surah_name_en, ayah_number, source_id, source_reference, source_url, audio_url, audio_source, status, source_verified, verified_at) values ('ad52cb98-0ea5-5e09-acd5-123fc004940c', 'quran', 'يَـٰبَنِىَّ ٱذْهَبُوا۟ فَتَحَسَّسُوا۟ مِن يُوسُفَ وَأَخِيهِ وَلَا تَا۟يْـَٔسُوا۟ مِن رَّوْحِ ٱللَّهِ ۖ إِنَّهُۥ لَا يَا۟يْـَٔسُ مِن رَّوْحِ ٱللَّهِ إِلَّا ٱلْقَوْمُ ٱلْكَـٰفِرُونَ', 12, 'يوسف', 'Yusuf', 87, 'f88c713d-6666-5de8-ac4d-65e5f14fe111', '12:87', 'https://quran.com/12/87', 'https://verses.quran.com/Alafasy/mp3/012087.mp3', 'Quran.com (Mishari al-Afasy)', 'published', true, now()) on conflict (id) do nothing;
insert into entry_translations (id, entry_id, lang, kind, body, source_name) values ('e97e5aa2-058d-5462-a859-a631b578b6dc', 'ad52cb98-0ea5-5e09-acd5-123fc004940c', 'de', 'translation', 'O meine Kinder, geht und erkundigt euch über Yusuf und seinen Bruder. Und gebt nicht die Hoffnung auf das Erbarmen Allahs auf. Es gibt die Hoffnung auf das Erbarmen Allahs nur das ungläubige Volk auf.', 'Frank Bubenheim and Nadeem (Quran.com)') on conflict (id) do nothing;
insert into entry_translations (id, entry_id, lang, kind, body, source_name) values ('1b147dd4-d7e9-5902-a976-bfb670b1bd0f', 'ad52cb98-0ea5-5e09-acd5-123fc004940c', 'en', 'translation', 'O my sons, go and find out about Joseph and his brother and despair not of relief from Allāh. Indeed, no one despairs of relief from Allāh except the disbelieving people."', 'Saheeh International (Quran.com)') on conflict (id) do nothing;
insert into entry_translations (id, entry_id, lang, kind, body, source_name) values ('08d9f8a0-342d-527d-ae54-2ad9b645b83d', 'ad52cb98-0ea5-5e09-acd5-123fc004940c', 'ar', 'explanation', 'ما تيأسوش من رحمة الله، الفرج كيجي.', null) on conflict (id) do nothing;
insert into entry_emotions (entry_id, emotion_id) values ('ad52cb98-0ea5-5e09-acd5-123fc004940c', 'a745ea41-d3a7-5bc3-a25d-4524534d474e') on conflict do nothing;
insert into religious_entries (id, type, arabic_text, surah_number, surah_name_ar, surah_name_en, ayah_number, source_id, source_reference, source_url, audio_url, audio_source, status, source_verified, verified_at) values ('dae91262-b4b7-51ae-a825-debb02e5059b', 'quran', 'كُتِبَ عَلَيْكُمُ ٱلْقِتَالُ وَهُوَ كُرْهٌ لَّكُمْ ۖ وَعَسَىٰٓ أَن تَكْرَهُوا۟ شَيْـًٔا وَهُوَ خَيْرٌ لَّكُمْ ۖ وَعَسَىٰٓ أَن تُحِبُّوا۟ شَيْـًٔا وَهُوَ شَرٌّ لَّكُمْ ۗ وَٱللَّهُ يَعْلَمُ وَأَنتُمْ لَا تَعْلَمُونَ', 2, 'البقرة', 'Al-Baqarah', 216, 'f88c713d-6666-5de8-ac4d-65e5f14fe111', '2:216', 'https://quran.com/2/216', 'https://verses.quran.com/Alafasy/mp3/002216.mp3', 'Quran.com (Mishari al-Afasy)', 'published', true, now()) on conflict (id) do nothing;
insert into entry_translations (id, entry_id, lang, kind, body, source_name) values ('f4e8be2a-0d7c-5695-a909-30b2d8d6d189', 'dae91262-b4b7-51ae-a825-debb02e5059b', 'de', 'translation', 'Vorgeschrieben ist euch zu kämpfen, obwohl es euch zuwider ist. Aber vielleicht ist euch etwas zuwider, während es gut für euch ist, und vielleicht ist euch etwas lieb, während es schlecht für euch ist. Allah weiß, ihr aber wißt nicht.', 'Frank Bubenheim and Nadeem (Quran.com)') on conflict (id) do nothing;
insert into entry_translations (id, entry_id, lang, kind, body, source_name) values ('fe8e2e13-6dda-5dd4-a0eb-5b192a9001fb', 'dae91262-b4b7-51ae-a825-debb02e5059b', 'en', 'translation', 'Battle has been enjoined upon you while it is hateful to you. But perhaps you hate a thing and it is good for you; and perhaps you love a thing and it is bad for you. And Allāh knows, while you know not.', 'Saheeh International (Quran.com)') on conflict (id) do nothing;
insert into entry_translations (id, entry_id, lang, kind, body, source_name) values ('886539f4-8f8b-54da-a960-2a2ee8d355c5', 'dae91262-b4b7-51ae-a825-debb02e5059b', 'ar', 'explanation', 'ممكن تكره شي حاجة وفيها الخير ليك، والله كيعلم وانتما لا.', null) on conflict (id) do nothing;
insert into entry_emotions (entry_id, emotion_id) values ('dae91262-b4b7-51ae-a825-debb02e5059b', 'f66ac991-0301-508c-af43-5b31e3293d2d') on conflict do nothing;
insert into religious_entries (id, type, arabic_text, surah_number, surah_name_ar, surah_name_en, ayah_number, source_id, source_reference, source_url, audio_url, audio_source, status, source_verified, verified_at) values ('d07732e0-3713-5ec8-ad40-5625aadc0a35', 'quran', 'فَبِمَا رَحْمَةٍ مِّنَ ٱللَّهِ لِنتَ لَهُمْ ۖ وَلَوْ كُنتَ فَظًّا غَلِيظَ ٱلْقَلْبِ لَٱنفَضُّوا۟ مِنْ حَوْلِكَ ۖ فَٱعْفُ عَنْهُمْ وَٱسْتَغْفِرْ لَهُمْ وَشَاوِرْهُمْ فِى ٱلْأَمْرِ ۖ فَإِذَا عَزَمْتَ فَتَوَكَّلْ عَلَى ٱللَّهِ ۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلْمُتَوَكِّلِينَ', 3, 'آل عمران', 'Ali ''Imran', 159, 'f88c713d-6666-5de8-ac4d-65e5f14fe111', '3:159', 'https://quran.com/3/159', 'https://verses.quran.com/Alafasy/mp3/003159.mp3', 'Quran.com (Mishari al-Afasy)', 'published', true, now()) on conflict (id) do nothing;
insert into entry_translations (id, entry_id, lang, kind, body, source_name) values ('0bf9158e-e9da-5ab9-afe8-20f47dffb0e2', 'd07732e0-3713-5ec8-ad40-5625aadc0a35', 'de', 'translation', 'Durch Erbarmen von Allah bist du mild zu ihnen gewesen; wärst du aber schroff und hartherzig, so würden sie wahrlich rings um dich auseinanderlaufen. So verzeihe ihnen, bitte für sie um Vergebung und ziehe sie in den Angelegenheiten zu Rate. Und wenn du dich entschlossen hast, dann verlasse dich auf Allah! Gewiß, Allah liebt die sich (auf Ihn) Verlassenden.', 'Frank Bubenheim and Nadeem (Quran.com)') on conflict (id) do nothing;
insert into entry_translations (id, entry_id, lang, kind, body, source_name) values ('17b29e04-a14a-54dc-ae5e-2790821e497d', 'd07732e0-3713-5ec8-ad40-5625aadc0a35', 'en', 'translation', 'So by mercy from Allāh, [O Muḥammad], you were lenient with them. And if you had been rude [in speech] and harsh in heart, they would have disbanded from about you. So pardon them and ask forgiveness for them and consult them in the matter. And when you have decided, then rely upon Allāh. Indeed, Allāh loves those who rely [upon Him].', 'Saheeh International (Quran.com)') on conflict (id) do nothing;
insert into entry_translations (id, entry_id, lang, kind, body, source_name) values ('dddb1dd7-3339-5b3d-a003-6530b8ecc72b', 'd07732e0-3713-5ec8-ad40-5625aadc0a35', 'ar', 'explanation', 'ملي كتقرر، توكل على الله.', null) on conflict (id) do nothing;
insert into entry_emotions (entry_id, emotion_id) values ('d07732e0-3713-5ec8-ad40-5625aadc0a35', 'f66ac991-0301-508c-af43-5b31e3293d2d') on conflict do nothing;
insert into religious_entries (id, type, arabic_text, surah_number, surah_name_ar, surah_name_en, ayah_number, source_id, source_reference, source_url, audio_url, audio_source, status, source_verified, verified_at) values ('08baf0fe-7209-58ec-ae4e-3fce1fbdb1c5', 'quran', 'قَالَ إِنَّمَآ أَشْكُوا۟ بَثِّى وَحُزْنِىٓ إِلَى ٱللَّهِ وَأَعْلَمُ مِنَ ٱللَّهِ مَا لَا تَعْلَمُونَ', 12, 'يوسف', 'Yusuf', 86, 'f88c713d-6666-5de8-ac4d-65e5f14fe111', '12:86', 'https://quran.com/12/86', 'https://verses.quran.com/Alafasy/mp3/012086.mp3', 'Quran.com (Mishari al-Afasy)', 'published', true, now()) on conflict (id) do nothing;
insert into entry_translations (id, entry_id, lang, kind, body, source_name) values ('70d24f3c-62e4-53b6-a1ac-80c437c66576', '08baf0fe-7209-58ec-ae4e-3fce1fbdb1c5', 'de', 'translation', 'Er sagte: Ich klage meinen unerträglichen Kummer und meine Trauer nur Allah (allein), und ich weiß von Allah her, was ihr nicht wißt.', 'Frank Bubenheim and Nadeem (Quran.com)') on conflict (id) do nothing;
insert into entry_translations (id, entry_id, lang, kind, body, source_name) values ('ac0d6016-be84-5084-adfb-c2bad7188910', '08baf0fe-7209-58ec-ae4e-3fce1fbdb1c5', 'en', 'translation', 'He said, "I only complain of my suffering and my grief to Allāh, and I know from Allāh that which you do not know.', 'Saheeh International (Quran.com)') on conflict (id) do nothing;
insert into entry_translations (id, entry_id, lang, kind, body, source_name) values ('002b0d18-d733-5cd9-aa83-691ef338a979', '08baf0fe-7209-58ec-ae4e-3fce1fbdb1c5', 'ar', 'explanation', 'سيدنا يعقوب شكا همو وحزنو لله وحده.', null) on conflict (id) do nothing;
insert into entry_emotions (entry_id, emotion_id) values ('08baf0fe-7209-58ec-ae4e-3fce1fbdb1c5', '1de43123-dc44-5aea-ab96-c4a0dcff720d') on conflict do nothing;
insert into religious_entries (id, type, arabic_text, surah_number, surah_name_ar, surah_name_en, ayah_number, source_id, source_reference, source_url, audio_url, audio_source, status, source_verified, verified_at) values ('1031d586-7331-5f77-a04a-e6373fc1ccbd', 'quran', 'فَلَمَّا نَسُوا۟ مَا ذُكِّرُوا۟ بِهِۦ فَتَحْنَا عَلَيْهِمْ أَبْوَٰبَ كُلِّ شَىْءٍ حَتَّىٰٓ إِذَا فَرِحُوا۟ بِمَآ أُوتُوٓا۟ أَخَذْنَـٰهُم بَغْتَةً فَإِذَا هُم مُّبْلِسُونَ', 6, 'الأنعام', 'Al-An''am', 44, 'f88c713d-6666-5de8-ac4d-65e5f14fe111', '6:44', 'https://quran.com/6/44', 'https://verses.quran.com/Alafasy/mp3/006044.mp3', 'Quran.com (Mishari al-Afasy)', 'published', true, now()) on conflict (id) do nothing;
insert into entry_translations (id, entry_id, lang, kind, body, source_name) values ('35f8b256-2320-56a5-a987-35c45ab2b9af', '1031d586-7331-5f77-a04a-e6373fc1ccbd', 'de', 'translation', 'Als sie dann vergaßen, womit sie ermahnt worden waren, öffneten Wir ihnen die Tore zu allen Dingen. Als sie dann froh waren über das, was ihnen gegeben worden war, ergriffen Wir sie plötzlich. Da waren sie sogleich verzweifelt.', 'Frank Bubenheim and Nadeem (Quran.com)') on conflict (id) do nothing;
insert into entry_translations (id, entry_id, lang, kind, body, source_name) values ('02828a09-8ee1-56ac-ae57-f4450473f63e', '1031d586-7331-5f77-a04a-e6373fc1ccbd', 'en', 'translation', 'So when they forgot that by which they had been reminded, We opened to them the doors of every [good] thing until, when they rejoiced in that which they were given, We seized them suddenly, and they were [then] in despair.', 'Saheeh International (Quran.com)') on conflict (id) do nothing;
insert into entry_translations (id, entry_id, lang, kind, body, source_name) values ('a9436fb7-94b4-5099-aa7e-101fd163720d', '1031d586-7331-5f77-a04a-e6373fc1ccbd', 'ar', 'explanation', 'النعمة ماشي دليل على رضا الله. اللي نسى الله ممكن يتعطى كلشي ومن بعد يتاخذ منو فجأة، والرجوع لله دابا هو الخير.', null) on conflict (id) do nothing;
insert into entry_emotions (entry_id, emotion_id) values ('1031d586-7331-5f77-a04a-e6373fc1ccbd', 'f5632603-02f9-5df9-aed0-619f83563bd1') on conflict do nothing;
insert into entry_emotions (entry_id, emotion_id) values ('1031d586-7331-5f77-a04a-e6373fc1ccbd', '0296e2ef-96c0-5d63-a57e-4cf00252b71e') on conflict do nothing;
